package frc.robot.subsystems.Kicker;

import edu.wpi.first.math.util.Units;
import frc.lib.mechanisms.MechanismConfig;

/**
 * Kicker constants. Generated by 3161 Robot Setup on 2026-10-15 -- edit freely.
 * Gains start as physics estimates; tune them live on the dashboard under
 * Tuning/Kicker/Kicker/ and copy the good values back here.
 */
public final class KickerConstants {
    private KickerConstants() {
    }

    //While false the motor gets no output at all (brakes), and no button moves the kicker.
    public static final boolean ENABLED = true;

    public enum WantedState {
        STOW,
        DEPLOY
    }

    /**
     * What the subsystem is actually doing. The motor can't hold the kicker out, so DEPLOY ends in BRAKE
     * (motor off, brake mode, kicker settles on the bumper). BRAKE ignores DEPLOY -- only STOW leaves it.
     */
    public enum SystemState {
        STOWING,
        STOW,
        DEPLOYING,
        BRAKE
    }

    /** Longest DEPLOYING drives the motor before giving up and going to BRAKE, even if not at DEPLOY_POSITION. */
    public static final double DEPLOY_TIMEOUT_SECONDS = 2.0;

    /* ---------------- Kicker (pivot) ---------------- */

    public static final MechanismConfig KICKER = MechanismConfig.named("Kicker/Kicker")
            .withLeader(43)
            .withMotor(MechanismConfig.Motor.KRAKEN_X44)
            .withGearRatio(2.0)
            .withCurrentLimits(60.0, 120.0)
            .withArm(Units.inchesToMeters(8.0), Units.lbsToKilograms(1.0))
            .withZeroAt(Units.degreesToRotations(0.0))
            .withPositiveDirection(MechanismConfig.Direction.COUNTERCLOCKWISE)
            .withLimits(Units.degreesToRotations(0.0), Units.degreesToRotations(130.0))
            .withStartingPosition(Units.degreesToRotations(0.0))
            .withPID(50.0, 0.0, 0)
            .withFeedforward(0.0, 0.1843, 0.057)
            .withGravity(0.66)
            .withMotionMagic(Units.degreesToRotations(1500.0), Units.degreesToRotations(10000.0), 0.0)
            .withTolerance(Units.degreesToRotations(1.0));

    /* ---------------- State targets, in rotations, measured from the 0 set by withZeroAt ---------------- */

    public static final double STOW_POSITION = Units.degreesToRotations(0.0);
    public static final double DEPLOY_POSITION = Units.degreesToRotations(130.0);
}
